  ('3702140', 'LOCAL', 'Council Member', -3740007, 'Bo Hess', 'Bo', 'Hess', NULL, NULL, ARRAY['Roberto']::text[], '2024-12-01'::date, 'month', 'elected', 'ashevillenc.gov/government/meet-city-council/ (retrieved 2026-08-23)'),
  ('37021', 'COUNTY', 'Chair, Board of Commissioners', -3740008, 'Amanda Edwards', 'Amanda', 'Edwards', NULL, NULL, ARRAY[]::text[], '2024-12-01'::date, 'month', 'elected', 'media.buncombenc.gov/common/election/elected-officials.pdf (Buncombe County Election Services, retrieved 2026-08-23)'),
  ('37021', 'COUNTY', 'Sheriff', -3740015, 'Quentin E. Miller', 'Quentin', 'Miller', 'E', NULL, ARRAY[]::text[], '2018-01-01'::date, 'year', 'elected', 'buncombenc.gov/568/Sheriffs-Office ("since taking office in 2018"), retrieved 2026-08-23'),
