  ('buncombe-nc-commissioner-district-3', 'COUNTY', 'Commissioner, District 3', -3740013, 'Parker Sloan', 'Parker', 'Sloan', NULL, NULL, ARRAY[]::text[], '2020-12-01'::date, 'month', 'elected', 'media.buncombenc.gov/common/election/elected-officials.pdf (Buncombe County Election Services, retrieved 2026-08-23)'),
