-- ─── Payload guard ───────────────────────────────────────────────────────────
-- Four groups legitimately repeat a (geo_id, district_type, office_title) triple,
-- so this checks per-group COUNTS rather than rejecting any duplicate.
DO $$
DECLARE v_n int; v_dup int; v_grp int;
BEGIN
  SELECT count(*) INTO v_n FROM wave3_seed;
  IF v_n <> 17 THEN RAISE EXCEPTION 'seed payload: expected 17 rows, got %', v_n; END IF;

  SELECT count(*) INTO v_dup FROM (SELECT ext_id FROM wave3_seed GROUP BY ext_id HAVING count(*) > 1) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'seed payload: % duplicate external_id(s)', v_dup; END IF;

  SELECT count(*) INTO v_grp FROM wave3_seed
   WHERE geo_id = '3702140' AND district_type = 'LOCAL' AND office_title = 'Council Member';
  IF v_grp <> 6 THEN RAISE EXCEPTION 'seed payload: expected 6 Council Member rows, got %', v_grp; END IF;

  SELECT count(*) INTO v_grp FROM wave3_seed
   WHERE geo_id = 'buncombe-nc-commissioner-district-1' AND district_type = 'COUNTY' AND office_title = 'Commissioner, District 1';
  IF v_grp <> 2 THEN RAISE EXCEPTION 'seed payload: expected 2 Commissioner, District 1 rows, got %', v_grp; END IF;

  SELECT count(*) INTO v_grp FROM wave3_seed
   WHERE geo_id = 'buncombe-nc-commissioner-district-2' AND district_type = 'COUNTY' AND office_title = 'Commissioner, District 2';
  IF v_grp <> 2 THEN RAISE EXCEPTION 'seed payload: expected 2 Commissioner, District 2 rows, got %', v_grp; END IF;

  SELECT count(*) INTO v_grp FROM wave3_seed
   WHERE geo_id = 'buncombe-nc-commissioner-district-3' AND district_type = 'COUNTY' AND office_title = 'Commissioner, District 3';
  IF v_grp <> 2 THEN RAISE EXCEPTION 'seed payload: expected 2 Commissioner, District 3 rows, got %', v_grp; END IF;

  -- Every OTHER triple must be unique -- the genuinely single-seat titles.
  SELECT count(*) INTO v_dup FROM (
    SELECT geo_id, district_type, office_title FROM wave3_seed
    WHERE office_title NOT IN ('Council Member', 'Commissioner, District 1', 'Commissioner, District 2', 'Commissioner, District 3')
    GROUP BY geo_id, district_type, office_title HAVING count(*) > 1
  ) x;
  IF v_dup <> 0 THEN RAISE EXCEPTION 'seed payload: % unexpected duplicate single-seat key(s)', v_dup; END IF;
END $$;

-- ─── Politicians ─────────────────────────────────────────────────────────────

INSERT INTO essentials.politicians
  (external_id, full_name, first_name, last_name, middle_initial, name_suffix,
   alternate_names, is_incumbent, is_active, data_source)
SELECT s.ext_id, s.full_name, s.first_name, s.last_name, s.middle_initial, s.name_suffix,
       s.aliases, true, true, s.source
FROM wave3_seed s
ON CONFLICT (external_id) DO NOTHING;

-- ─── Occupancy, via the helper ───────────────────────────────────────────────

DO $$
DECLARE
  r record;
  v_seated int := 0;
BEGIN
  FOR r IN
    WITH office_rank AS (
      SELECT o.id AS office_id, d.geo_id, d.district_type, o.title,
             row_number() OVER (
               PARTITION BY d.geo_id, d.district_type, o.title ORDER BY o.id
             ) AS rn
      FROM essentials.offices o
      JOIN essentials.districts d ON d.id = o.district_id
      WHERE (d.geo_id = '3702140' AND d.district_type = 'LOCAL')
         OR (d.geo_id = '37021' AND d.district_type = 'COUNTY')
         OR (d.mtfcc = 'X0034')
    ),
    seed_rank AS (
      SELECT s.*,
             row_number() OVER (
               PARTITION BY s.geo_id, s.district_type, s.office_title ORDER BY s.ext_id
             ) AS rn
      FROM wave3_seed s
    )
    SELECT sr.term_start, sr.start_precision, sr.how_started, sr.source,
           orr.office_id, p.id AS politician_id
    FROM seed_rank sr
    JOIN office_rank orr
      ON orr.geo_id = sr.geo_id
     AND orr.district_type = sr.district_type
     AND orr.title = sr.office_title
     AND orr.rn = sr.rn
    JOIN essentials.politicians p ON p.external_id = sr.ext_id
    WHERE NOT EXISTS (
      SELECT 1 FROM essentials.office_terms t
      WHERE t.office_id = orr.office_id AND t.politician_id = p.id
    )
  LOOP
    PERFORM essentials.seat_officeholder(
      r.office_id, r.politician_id, r.term_start,
      r.source,
      r.how_started,
      r.start_precision
    );
    v_seated := v_seated + 1;
  END LOOP;
  RAISE NOTICE 'seated % Asheville/Buncombe official(s)', v_seated;
END $$;

-- ─── Post-verify gate ────────────────────────────────────────────────────────
DO $$
DECLARE
  v_pol int; v_seated int; v_appointed int; v_homonym int; v_n int;
BEGIN
  SELECT count(*) INTO v_pol
  FROM essentials.politicians WHERE external_id BETWEEN -3740017 AND -3740001;
  IF v_pol <> 17 THEN RAISE EXCEPTION 'CA_0010: officials inserted: expected 17, got %', v_pol; END IF;

  -- count(och.politician_id), NOT count(*): office_current_holder LEFT JOINs from
  -- offices, so a vacancy is a NULL politician_id, never an absent row. count(*)
  -- would pass vacuously with every seat empty.
  SELECT count(och.politician_id) INTO v_seated
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE (d.geo_id = '3702140' AND d.district_type = 'LOCAL')
      OR (d.geo_id = '37021' AND d.district_type = 'COUNTY')
      OR (d.mtfcc = 'X0034');
  IF v_seated <> 17 THEN RAISE EXCEPTION 'CA_0010: expected 17 seated officials, found %', v_seated; END IF;

  -- Exactly 2 SEATED commissioners per district -- again per-district, because a
  -- total of 6 is what the chamber-scoped top-up bug would also produce.
  SELECT count(och.politician_id) INTO v_n
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE d.geo_id = 'buncombe-nc-commissioner-district-1' AND d.mtfcc = 'X0034';
  IF v_n <> 2 THEN RAISE EXCEPTION 'CA_0010: commission district 1 has % seated commissioner(s), expected 2', v_n; END IF;
  SELECT count(och.politician_id) INTO v_n
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE d.geo_id = 'buncombe-nc-commissioner-district-2' AND d.mtfcc = 'X0034';
  IF v_n <> 2 THEN RAISE EXCEPTION 'CA_0010: commission district 2 has % seated commissioner(s), expected 2', v_n; END IF;
  SELECT count(och.politician_id) INTO v_n
    FROM essentials.offices o
    JOIN essentials.districts d ON d.id = o.district_id
    LEFT JOIN essentials.office_current_holder och ON och.office_id = o.id
   WHERE d.geo_id = 'buncombe-nc-commissioner-district-3' AND d.mtfcc = 'X0034';
  IF v_n <> 2 THEN RAISE EXCEPTION 'CA_0010: commission district 3 has % seated commissioner(s), expected 2', v_n; END IF;

  SELECT count(*) INTO v_appointed
    FROM essentials.office_terms t
    JOIN essentials.politicians p ON p.id = t.politician_id
   WHERE p.external_id BETWEEN -3740017 AND -3740001 AND t.how_started = 'appointed';
  IF v_appointed <> 4 THEN RAISE EXCEPTION 'CA_0010: expected 4 appointed term(s), found %', v_appointed; END IF;

  -- 🔴 Cross-state homonym assertion: no wave-3 seat may resolve to someone who
  -- also holds an office outside NC. This is the Mike Lee guard.
  SELECT count(*) INTO v_homonym
  FROM essentials.politicians p
  JOIN essentials.office_current_holder och ON och.politician_id = p.id
  JOIN essentials.offices o ON o.id = och.office_id
  JOIN essentials.districts d ON d.id = o.district_id
   AND ((d.geo_id = '3702140' AND d.district_type = 'LOCAL')
     OR (d.geo_id = '37021' AND d.district_type = 'COUNTY')
     OR (d.mtfcc = 'X0034'))
  JOIN essentials.office_current_holder och2 ON och2.politician_id = p.id
  JOIN essentials.offices o2 ON o2.id = och2.office_id
  JOIN essentials.districts d2 ON d2.id = o2.district_id AND lower(d2.state) <> 'nc';
  IF v_homonym <> 0 THEN RAISE EXCEPTION
    'CA_0010: % wave-3 seat(s) resolved to an out-of-state politician -- the Mike Lee failure', v_homonym; END IF;

  RAISE NOTICE 'CA_0010 OK -- 17 officials seated, 4 by appointment, 0 homonyms.';
END $$;

COMMIT;
